def balanced_brackets(text):
    stack = []
    for char in text:
        if char == '(':
            stack.append(char)
        elif char == '[':
            stack.append(char)
        elif char == '{':
            stack.append(char)
        else:
            # If we reach here, all brackets are matched
            break

        # If stack is empty when closing bracket, 
        # there's an unmatched opening bracket
        if not stack:
