    # Stack is empty, meaning all brackets were matched correctly
    return len(stack) == 0

def balanced_brackets(text):
    balance = 0
    opening_bracket_map = {"(", "[", "{"}
    closing_bracket_map = {")": "(", "]": "]", "}": "{"}

    for char in text:
        if char in opening_bracket_map:
            balance += 1
        elif char in closing_bracket_map.values():
            balance -= 1

        if balance == 0:
            return False

    return balance == 0

